import * as T from './three.module.js';import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
// Batch within each articulated part, retaining head/limb/wheel pivots.
export function batchRigidDetails(root){for(const o of [...root.children])if(o.isGroup)batchRigidDetails(o);root.updateMatrix();const groups=new Map();for(const o of [...root.children]){if(!o.isMesh||o.isSkinnedMesh||o.isInstancedMesh||Array.isArray(o.material)||!o.visible)continue;const m=o.material;if(m.map||!o.geometry.attributes.uv)continue;const key=[m.type,m.color?.getHex(),m.roughness,m.metalness,m.emissive?.getHex(),m.emissiveIntensity,m.transparent,m.opacity].join('/');if(!groups.has(key))groups.set(key,{mat:m,list:[],old:[]});const b=groups.get(key),g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();o.updateMatrix();g.applyMatrix4(o.matrix);b.list.push(g);b.old.push(o);}for(const b of groups.values()){if(b.list.length<2){for(const g of b.list)g.dispose();continue;}const merged=mergeGeometries(b.list);if(!merged)continue;for(const o of b.old)root.remove(o);const o=new T.Mesh(merged,b.mat);o.name='Batched articulated detail';root.add(o);for(const g of b.list)g.dispose();}return root;}
